import hashlib, json, os

CHUNK = 64 * 1024
MAX_PER_SCAN = 8 * 1024 * 1024

def head_hash(f):
    f.seek(0)
    return hashlib.sha256(f.read(4096)).hexdigest()

def read_new(path, state):
    st = os.stat(path)
    row = state.get(path, {'inode': st.st_ino, 'offset': 0, 'head_hash': ''})
    with open(path, 'rb') as f:
        hh = head_hash(f)
        # tricky part: a replaced or truncated file must restart at 0
        if st.st_ino != row['inode'] or st.st_size < row['offset'] or (row['head_hash'] and hh != row['head_hash']):
            row = {'inode': st.st_ino, 'offset': 0, 'head_hash': hh}
        f.seek(row['offset'])
        buf, total = b'', 0
        while total < MAX_PER_SCAN:
            chunk = f.read(CHUNK)
            if not chunk:
                break
            buf += chunk
            total += len(chunk)
    cut = buf.rfind(b'\n')
    if cut < 0:
        return [], row['offset'], 0       # only a partial line so far
    complete = buf[:cut + 1]
    out, bad = [], 0
    for raw in complete.split(b'\n'):
        if not raw:
            continue
        try:
            out.append(json.loads(raw))
        except ValueError:
            bad += 1
    state[path] = {'inode': st.st_ino, 'offset': row['offset'] + len(complete), 'head_hash': hh}
    return out, row['offset'] + len(complete), bad

