import math, time, unicodedata
from collections import Counter

def entropy(s):
    n = len(s)
    return -sum(c / n * math.log2(c / n) for c in Counter(s).values())

def redact(text, rules, budget_ms=50):
    t0 = time.monotonic()
    text = unicodedata.normalize('NFKC', text)       # defeats look-alike characters
    low = text.lower()
    spans = []
    for r in rules:
        if r.keywords and not any(k in low for k in r.keywords):
            continue                                  # cheap prefilter
        for m in r.rx.finditer(text):
            tok = m.group(0)
            if r.entropy and entropy(tok) < r.entropy:
                continue
            spans.append((m.start(), m.end(), r.id))
        if (time.monotonic() - t0) * 1000 > budget_ms:
            # tricky part: fail closed, send no text at all
            return {'text_redacted': '', 'redactions': [], 'content_dropped': True}
    spans.sort()
    merged = []
    for s, e, rid in spans:
        if merged and s <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(e, merged[-1][1]), merged[-1][2])
        else:
            merged.append((s, e, rid))
    out, pos = [], 0
    for s, e, rid in merged:
        out.append(text[pos:s]); out.append(f'[REDACTED:{rid}]'); pos = e
    out.append(text[pos:])
    return {'text_redacted': ''.join(out),
            'redactions': [{'rule_id': r, 'start': s, 'end': e} for s, e, r in merged],
            'content_dropped': False}

