import hashlib, hmac, json, keyring

SERVICE = 'brain-companion'
NOTICE_VERSION = 4

def _key():
    k = keyring.get_password(SERVICE, 'flag-key')
    if k is None:
        import secrets
        k = secrets.token_hex(32)
        keyring.set_password(SERVICE, 'flag-key', k)
    return k.encode()

def _mac(p):
    msg = f"{p['paused']}|{p['counter']}|{p.get('since','')}".encode()
    return hmac.new(_key(), msg, hashlib.sha256).hexdigest()

def save_state(path, paused, counter, since, consent):
    p = {'paused': paused, 'counter': counter, 'since': since, 'consent': consent}
    p['mac'] = _mac(p)
    open(path, 'w').write(json.dumps(p))

def capture_allowed(path):
    try:
        p = json.load(open(path))
    except (OSError, ValueError):
        return False                                   # no state means no capture
    # tricky part: a bad signature means paused, never 'unpaused'
    if not hmac.compare_digest(p.get('mac', ''), _mac(p)):
        return False
    if p['paused']:
        return False
    if p['consent'].get('notice_version') != NOTICE_VERSION:
        return False
    return keyring.get_password(SERVICE, 'device-token') is not None

