import asyncio, os, random
import httpx

BASE, CAP = 2.0, 300.0

def real_under(path, roots):
    p = os.path.realpath(path)
    return any(p == r or p.startswith(r + os.sep) for r in roots)

async def send_with_backoff(client, batch, token, allowed):
    n = 0
    while True:
        if not allowed():                 # pause check right before the POST
            return None
        try:
            r = await client.post('/v1/turns', json=batch,
                                  headers={'Authorization': f'Bearer {token()}'}, timeout=20)
            if r.status_code == 202:
                return r.json()['acked_through']
            if r.status_code == 401:
                raise PermissionError('relink')
        except httpx.TransportError:
            pass
        delay = min(CAP, BASE * 2 ** n) * random.uniform(0.5, 1.0)
        n += 1
        await asyncio.sleep(delay)

async def run_file(client, path, state, roots, read_new, build_batch, allowed, token):
    if not real_under(path, roots):
        return                             # symlink escape
    lines, new_off, bad = read_new(path, state)
    if not lines:
        return
    acked = await send_with_backoff(client, build_batch(path, lines), token, allowed)
    if acked is not None:
        state[path]['acked_offset'] = new_off     # advance only after the 2xx

