import base64, hashlib
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey
from cryptography.exceptions import InvalidSignature

def vkey(v):
    return tuple(int(x) for x in v.split('.'))

def apply_update(m, package, current, pinned_channel, pubkey):
    msg = f"{m['version']}|{m['sha256']}|{m['min_version']}|{m['channel']}".encode()
    try:
        Ed25519PublicKey.from_public_bytes(pubkey).verify(base64.b64decode(m['signature']), msg)
    except (InvalidSignature, ValueError):
        return False
    if m['channel'] != pinned_channel:
        return False                         # pinned channel only
    if hashlib.sha256(package).hexdigest() != m['sha256']:
        return False
    # tricky part: refuse any version that is not strictly higher
    if vkey(m['version']) <= vkey(current):
        return False
    install_atomically(package)              # keep the old build until the new one verifies
    return True

def heartbeat_step(get, device_id, stop_daemon, last_ok):
    try:
        j = get(f'/v1/heartbeat?device={device_id}')
        if j.get('disable'):
            stop_daemon('remote disable')
        return j, 0
    except OSError:
        return None, last_ok + 300            # seconds without an answer

def self_pause_needed(seconds_without_answer, limit=24 * 3600):
    return seconds_without_answer >= limit
